<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('appointments.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'customer_appointments');
if($_SERVER['REQUEST_METHOD']==='POST'){if(fpost('action')==='update'){$pdo->prepare('UPDATE customer_appointments SET status=?,confirmed_start=?,assigned_to=?,staff_notes=? WHERE id=?')->execute([fpost('status'),fpost('confirmed_start')?:null,fint('assigned_to'),fpost('staff_notes')?:null,fint('id')]);flash('success','Appointment updated.');}staff_redirect('staff/pages/appointments.php');}
$staffs=staff_options($pdo);$rows=db_rows($pdo,'SELECT a.*,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) assigned_name FROM customer_appointments a LEFT JOIN staff s ON s.id=a.assigned_to ORDER BY COALESCE(a.confirmed_start,a.requested_start)');$pageTitle='Customer Appointments';require __DIR__.'/../../includes/staff/header.php';module_head('Customers','Appointments','Review consultation, measurement and showroom requests from customers.');?>
<section class="staff-panel table-panel"><table><thead><tr><th>Customer</th><th>Type</th><th>Requested</th><th>Status</th><th>Assignment / confirmation</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['customer_name'])?></b><small><?=h($r['customer_phone']?:$r['customer_email'])?></small></td><td><?=h(str_replace('_',' ',$r['appointment_type']))?></td><td><?=h(date('j M Y, g:i A',strtotime($r['requested_start'])))?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['requested','confirmed','completed','cancelled','no_show'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><input type="datetime-local" name="confirmed_start" value="<?=h($r['confirmed_start']?date('Y-m-d\TH:i',strtotime($r['confirmed_start'])):'')?>"><select name="assigned_to"><option value="">Unassigned</option><?php foreach($staffs as $s):?><option value="<?=$s['id']?>" <?=$r['assigned_to']==$s['id']?'selected':''?>><?=hopt($s['first_name'],$s['last_name'])?></option><?php endforeach?></select><input name="staff_notes" value="<?=h($r['staff_notes']?:'')?>" placeholder="Notes"><button class="btn">Save</button></form></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>